-- G2.4 deterministic Silver execution. Execute this entire file in one Snowflake session.
-- Bronze is read only. INSERT OVERWRITE makes trusted state rerunnable; audit history is append-only.
USE ROLE TRUSTED_AI_DATA_ENGINEER;
USE DATABASE TRUSTED_AI_GOVERNANCE;
ALTER SESSION SET TIMEZONE='UTC';
SET TRANSFORMATION_RUN_ID=(SELECT UUID_STRING());
SET TRACE_ID=(SELECT UUID_STRING());
SET TRANSFORMATION_STARTED_AT=(SELECT CURRENT_TIMESTAMP());
INSERT INTO AUDIT.TRANSFORMATION_RUN SELECT $TRANSFORMATION_RUN_ID,$TRACE_ID,$TRANSFORMATION_STARTED_AT,NULL,CURRENT_ROLE(),'STARTED',LAST_QUERY_ID();

CREATE OR REPLACE TEMP TABLE G2_4_FAILURES AS
WITH APPROVED_PAYMENT_CURRENCY AS (
 SELECT DISTINCT P._SOURCE_FILE_CONTENT_KEY,P._SOURCE_FILE_ROW_NUMBER
 FROM BRONZE.PAYMENT_RAW P
 JOIN BRONZE.REFERENCE_PAYMENT_THRESHOLD_RAW R
   ON UPPER(TRIM(P.CURRENCY_CODE))=UPPER(TRIM(R.CURRENCY_CODE))
  AND TRY_TO_DATE(P.PAYMENT_DATE) BETWEEN TRY_TO_DATE(R.EFFECTIVE_DATE)
      AND COALESCE(TRY_TO_DATE(R.EXPIRY_DATE),'9999-12-31'::DATE)
  AND UPPER(TRIM(R.APPROVAL_STATUS))='APPROVED'
), DUP AS (SELECT _SOURCE_FILE_CONTENT_KEY,_SOURCE_FILE_ROW_NUMBER,ROW_NUMBER() OVER(PARTITION BY TRIM(SOURCE_REFERENCE) ORDER BY IFF(PAYMENT_ID='PAY_DQ_DUP_001',1,0),_SOURCE_FILE_CONTENT_KEY,_SOURCE_FILE_ROW_NUMBER,PAYMENT_ID) RN FROM BRONZE.PAYMENT_RAW WHERE SOURCE_REFERENCE IS NOT NULL),
PAY AS (
 SELECT P.*,D.RN,A.CUSTOMER_ID ACCOUNT_CUSTOMER,
   IFF(P.CUSTOMER_ID IS NULL,'SLV-PAY-001',IFF(APC._SOURCE_FILE_CONTENT_KEY IS NULL,'SLV-PAY-002',IFF(TRY_TO_DECIMAL(P.PAYMENT_AMOUNT,18,2)<0,'SLV-PAY-003',IFF(D.RN>1,'SLV-PAY-004',IFF(A.ACCOUNT_ID IS NULL OR P.CUSTOMER_ID<>A.CUSTOMER_ID,'SLV-REL-001',IFF(TRY_TO_TIMESTAMP_NTZ(P.PAYMENT_TIMESTAMP) IS NULL OR TRY_TO_DATE(P.PAYMENT_DATE) IS NULL OR TRY_TO_DECIMAL(P.PAYMENT_AMOUNT,18,2) IS NULL,'SLV-STD-001',NULL)))))) RULE_ID
 FROM BRONZE.PAYMENT_RAW P
 LEFT JOIN APPROVED_PAYMENT_CURRENCY APC USING(_SOURCE_FILE_CONTENT_KEY,_SOURCE_FILE_ROW_NUMBER)
 LEFT JOIN DUP D USING(_SOURCE_FILE_CONTENT_KEY,_SOURCE_FILE_ROW_NUMBER)
 LEFT JOIN BRONZE.ACCOUNT_RAW A ON P.ACCOUNT_ID=A.ACCOUNT_ID
), EXC AS (
 SELECT E.*,IFF(E.EXCEPTION_REASON_CODE IS NULL,'SLV-EXC-002',IFF(P.PAYMENT_ID IS NULL OR E.CUSTOMER_ID<>P.CUSTOMER_ID OR E.ACCOUNT_ID<>P.ACCOUNT_ID,'SLV-REL-001',IFF(TRY_TO_TIMESTAMP_NTZ(E.EXCEPTION_TIMESTAMP)<TRY_TO_TIMESTAMP_NTZ(P.PAYMENT_TIMESTAMP),'SLV-EXC-001',IFF(R.EXCEPTION_REASON_CODE IS NULL,'SLV-EXC-003',IFF(TRY_TO_TIMESTAMP_NTZ(E.EXCEPTION_TIMESTAMP) IS NULL OR TRY_TO_DATE(E.EXCEPTION_DATE) IS NULL,'SLV-STD-001',NULL))))) RULE_ID
 FROM BRONZE.PAYMENT_EXCEPTION_RAW E LEFT JOIN BRONZE.PAYMENT_RAW P ON E.PAYMENT_ID=P.PAYMENT_ID
 LEFT JOIN BRONZE.REFERENCE_EXCEPTION_REASON_RAW R ON E.EXCEPTION_REASON_CODE=R.EXCEPTION_REASON_CODE AND UPPER(TRIM(R.ACTIVE_FLAG))='TRUE' AND TRY_TO_DATE(E.EXCEPTION_DATE) BETWEEN TRY_TO_DATE(R.EFFECTIVE_DATE) AND COALESCE(TRY_TO_DATE(R.EXPIRY_DATE),'9999-12-31'::DATE)
), SLA AS (
 SELECT S.*,IFF(E.EXCEPTION_ID IS NULL OR E.RULE_ID IS NOT NULL,'SLV-REL-001',IFF(TRY_TO_TIMESTAMP_NTZ(S.SLA_DUE_TIMESTAMP)<TRY_TO_TIMESTAMP_NTZ(S.SLA_START_TIMESTAMP),'SLV-SLA-001',IFF(TRY_TO_TIMESTAMP_NTZ(S.SLA_DUE_TIMESTAMP) IS NULL OR TRY_TO_TIMESTAMP_NTZ(S.SLA_START_TIMESTAMP) IS NULL,'SLV-STD-001',NULL))) RULE_ID
 FROM BRONZE.SLA_EVENT_RAW S LEFT JOIN EXC E ON S.EXCEPTION_ID=E.EXCEPTION_ID
)
SELECT 'PAYMENT' SOURCE_ENTITY,PAYMENT_ID SOURCE_RECORD_ID,_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_SOURCE_FILE_CONTENT_KEY,_INGESTION_RUN_ID,_SYNTHETIC_FLAG,RULE_ID FROM PAY WHERE RULE_ID IS NOT NULL
UNION ALL SELECT 'PAYMENT_EXCEPTION',EXCEPTION_ID,_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_SOURCE_FILE_CONTENT_KEY,_INGESTION_RUN_ID,_SYNTHETIC_FLAG,RULE_ID FROM EXC WHERE RULE_ID IS NOT NULL
UNION ALL SELECT 'SLA_EVENT',SLA_EVENT_ID,_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_SOURCE_FILE_CONTENT_KEY,_INGESTION_RUN_ID,_SYNTHETIC_FLAG,RULE_ID FROM SLA WHERE RULE_ID IS NOT NULL;

MERGE INTO SILVER_QUARANTINE.REJECTED_RECORD T USING (
 SELECT SHA2(CONCAT_WS('|',$TRANSFORMATION_RUN_ID,F.SOURCE_ENTITY,F._SOURCE_FILE_CONTENT_KEY,F._SOURCE_FILE_ROW_NUMBER,F.RULE_ID),256) QUARANTINE_ID,$TRANSFORMATION_RUN_ID TRANSFORMATION_RUN_ID,$TRACE_ID TRACE_ID,F.SOURCE_ENTITY,F.SOURCE_RECORD_ID,
 CONCAT(F.SOURCE_ENTITY,'|',F._SOURCE_FILE_CONTENT_KEY,'|',F._SOURCE_FILE_ROW_NUMBER) BRONZE_RECORD_REFERENCE,F._SOURCE_FILE_NAME SOURCE_FILE_NAME,F._SOURCE_FILE_ROW_NUMBER SOURCE_FILE_ROW_NUMBER,F._INGESTION_RUN_ID INGESTION_RUN_ID,
 F.RULE_ID AS DQ_RULE_ID,R.DQ_SCENARIO_ID,R.DQ_SEVERITY,'QUARANTINE' GOVERNANCE_OUTCOME,R.RULE_DESCRIPTION QUARANTINE_REASON,CURRENT_TIMESTAMP() QUARANTINED_AT,F._SYNTHETIC_FLAG SYNTHETIC_FLAG
 FROM G2_4_FAILURES F JOIN GOVERNANCE.DQ_RULE_CATALOG R ON F.RULE_ID=R.DQ_RULE_ID
) S ON T.QUARANTINE_ID=S.QUARANTINE_ID
WHEN MATCHED THEN UPDATE SET TRANSFORMATION_RUN_ID=S.TRANSFORMATION_RUN_ID,TRACE_ID=S.TRACE_ID,QUARANTINED_AT=S.QUARANTINED_AT
WHEN NOT MATCHED THEN INSERT VALUES(S.QUARANTINE_ID,S.TRANSFORMATION_RUN_ID,S.TRACE_ID,S.SOURCE_ENTITY,S.SOURCE_RECORD_ID,S.BRONZE_RECORD_REFERENCE,S.SOURCE_FILE_NAME,S.SOURCE_FILE_ROW_NUMBER,S.INGESTION_RUN_ID,S.DQ_RULE_ID,S.DQ_SCENARIO_ID,S.DQ_SEVERITY,S.GOVERNANCE_OUTCOME,S.QUARANTINE_REASON,S.QUARANTINED_AT,S.SYNTHETIC_FLAG);

-- Minimized CUSTOMER intentionally excludes DOB, email, phone, street address, postal code and balance.
INSERT OVERWRITE INTO SILVER.CUSTOMER SELECT TRIM(CUSTOMER_ID),UPPER(TRIM(CUSTOMER_TYPE)),UPPER(TRIM(CUSTOMER_SEGMENT)),UPPER(TRIM(RISK_TIER)),UPPER(TRIM(CUSTOMER_STATUS)),TRY_TO_DATE(CREATED_DATE),TRIM(CUSTOMER_NAME),TRIM(CITY),TRIM(STATE),UPPER(TRIM(COUNTRY)),CONCAT(LEFT(TRIM(CUSTOMER_NAME),1),'***'),_SOURCE_ID,CONCAT('CUSTOMER|',_SOURCE_FILE_CONTENT_KEY,'|',_SOURCE_FILE_ROW_NUMBER),_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),_SYNTHETIC_FLAG,'PASS' FROM BRONZE.CUSTOMER_RAW WHERE CUSTOMER_ID IS NOT NULL AND TRY_TO_DATE(CREATED_DATE) IS NOT NULL;
INSERT OVERWRITE INTO SILVER.ACCOUNT SELECT TRIM(A.ACCOUNT_ID),TRIM(A.CUSTOMER_ID),UPPER(TRIM(A.ACCOUNT_TYPE)),UPPER(TRIM(A.ACCOUNT_STATUS)),UPPER(TRIM(A.CURRENCY_CODE)),TRY_TO_DATE(A.OPEN_DATE),UPPER(TRIM(A.ACCOUNT_COUNTRY)),UPPER(TRIM(A.RELATIONSHIP_TIER)),A._SOURCE_ID,CONCAT('ACCOUNT|',A._SOURCE_FILE_CONTENT_KEY,'|',A._SOURCE_FILE_ROW_NUMBER),A._SOURCE_FILE_NAME,A._SOURCE_FILE_ROW_NUMBER,A._INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),A._SYNTHETIC_FLAG,'PASS' FROM BRONZE.ACCOUNT_RAW A JOIN SILVER.CUSTOMER C ON A.CUSTOMER_ID=C.CUSTOMER_ID WHERE A.ACCOUNT_ID IS NOT NULL AND TRY_TO_DATE(A.OPEN_DATE) IS NOT NULL;
INSERT OVERWRITE INTO SILVER.REFERENCE_EXCEPTION_REASON SELECT TRIM(EXCEPTION_REASON_CODE),TRIM(EXCEPTION_CATEGORY),TRIM(BUSINESS_DEFINITION),UPPER(TRIM(DEFAULT_SEVERITY)),TRY_TO_BOOLEAN(MANUAL_REVIEW_DEFAULT),TRY_TO_BOOLEAN(ACTIVE_FLAG),TRY_TO_DATE(EFFECTIVE_DATE),TRY_TO_DATE(EXPIRY_DATE),_SOURCE_ID,CONCAT('REFERENCE_EXCEPTION_REASON|',_SOURCE_FILE_CONTENT_KEY,'|',_SOURCE_FILE_ROW_NUMBER),_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),_SYNTHETIC_FLAG,'PASS' FROM BRONZE.REFERENCE_EXCEPTION_REASON_RAW WHERE EXCEPTION_REASON_CODE IS NOT NULL AND TRY_TO_DATE(EFFECTIVE_DATE) IS NOT NULL;
INSERT OVERWRITE INTO SILVER.REFERENCE_PAYMENT_THRESHOLD SELECT TRIM(THRESHOLD_ID),UPPER(TRIM(CURRENCY_CODE)),TRY_TO_DECIMAL(HIGH_VALUE_THRESHOLD,18,2),TRY_TO_DATE(EFFECTIVE_DATE),TRY_TO_DATE(EXPIRY_DATE),UPPER(TRIM(APPROVAL_STATUS)),_SOURCE_ID,CONCAT('REFERENCE_PAYMENT_THRESHOLD|',_SOURCE_FILE_CONTENT_KEY,'|',_SOURCE_FILE_ROW_NUMBER),_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),_SYNTHETIC_FLAG,'PASS' FROM BRONZE.REFERENCE_PAYMENT_THRESHOLD_RAW WHERE THRESHOLD_ID IS NOT NULL AND TRY_TO_DECIMAL(HIGH_VALUE_THRESHOLD,18,2)>=0 AND TRY_TO_DATE(EFFECTIVE_DATE) IS NOT NULL;
INSERT OVERWRITE INTO SILVER.PAYMENT SELECT TRIM(P.PAYMENT_ID),TRIM(P.ACCOUNT_ID),TRIM(P.CUSTOMER_ID),TRY_TO_TIMESTAMP_NTZ(P.PAYMENT_TIMESTAMP),TRY_TO_DATE(P.PAYMENT_DATE),UPPER(TRIM(P.PAYMENT_TYPE)),UPPER(TRIM(P.PAYMENT_CHANNEL)),UPPER(TRIM(P.CURRENCY_CODE)),TRY_TO_DECIMAL(P.PAYMENT_AMOUNT,18,2),UPPER(TRIM(P.BENEFICIARY_COUNTRY)),UPPER(TRIM(P.BENEFICIARY_TYPE)),UPPER(TRIM(P.PAYMENT_STATUS)),UPPER(TRIM(P.PROCESSING_SYSTEM)),TRY_TO_DATE(P.REQUESTED_EXECUTION_DATE),TRY_TO_DATE(P.ACTUAL_EXECUTION_DATE),TRIM(P.SOURCE_REFERENCE),'CANONICAL',P._SOURCE_ID,CONCAT('PAYMENT|',P._SOURCE_FILE_CONTENT_KEY,'|',P._SOURCE_FILE_ROW_NUMBER),P._SOURCE_FILE_NAME,P._SOURCE_FILE_ROW_NUMBER,P._INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),P._SYNTHETIC_FLAG,'PASS' FROM BRONZE.PAYMENT_RAW P WHERE NOT EXISTS(SELECT 1 FROM G2_4_FAILURES F WHERE F.SOURCE_ENTITY='PAYMENT' AND F._SOURCE_FILE_CONTENT_KEY=P._SOURCE_FILE_CONTENT_KEY AND F._SOURCE_FILE_ROW_NUMBER=P._SOURCE_FILE_ROW_NUMBER);
INSERT OVERWRITE INTO SILVER.PAYMENT_EXCEPTION SELECT TRIM(E.EXCEPTION_ID),TRIM(E.PAYMENT_ID),TRIM(E.CUSTOMER_ID),TRIM(E.ACCOUNT_ID),TRY_TO_TIMESTAMP_NTZ(E.EXCEPTION_TIMESTAMP),TRY_TO_DATE(E.EXCEPTION_DATE),UPPER(TRIM(E.EXCEPTION_TYPE)),TRIM(E.EXCEPTION_REASON_CODE),R.EXCEPTION_CATEGORY,R.BUSINESS_DEFINITION,COALESCE(UPPER(TRIM(E.SEVERITY)),R.DEFAULT_SEVERITY),UPPER(TRIM(E.EXCEPTION_STATUS)),TRIM(E.ASSIGNED_TEAM),TRIM(E.ASSIGNED_ANALYST_ID),UPPER(TRIM(E.RESOLUTION_STATUS)),TRIM(E.RESOLUTION_CODE),TRY_TO_TIMESTAMP_NTZ(E.RESOLVED_TIMESTAMP),TRY_TO_TIMESTAMP_NTZ(E.SLA_DUE_TIMESTAMP),IFF(P.PAYMENT_AMOUNT>=T.HIGH_VALUE_THRESHOLD,TRUE,FALSE),COALESCE(TRY_TO_BOOLEAN(E.REQUIRES_MANUAL_REVIEW),R.MANUAL_REVIEW_DEFAULT),E._SOURCE_ID,CONCAT('PAYMENT_EXCEPTION|',E._SOURCE_FILE_CONTENT_KEY,'|',E._SOURCE_FILE_ROW_NUMBER),E._SOURCE_FILE_NAME,E._SOURCE_FILE_ROW_NUMBER,E._INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),E._SYNTHETIC_FLAG,'PASS' FROM BRONZE.PAYMENT_EXCEPTION_RAW E JOIN SILVER.PAYMENT P ON E.PAYMENT_ID=P.PAYMENT_ID JOIN SILVER.REFERENCE_EXCEPTION_REASON R ON E.EXCEPTION_REASON_CODE=R.EXCEPTION_REASON_CODE AND R.ACTIVE_FLAG AND TRY_TO_DATE(E.EXCEPTION_DATE) BETWEEN R.EFFECTIVE_DATE AND COALESCE(R.EXPIRY_DATE,'9999-12-31') LEFT JOIN SILVER.REFERENCE_PAYMENT_THRESHOLD T ON P.CURRENCY_CODE=T.CURRENCY_CODE AND T.APPROVAL_STATUS='APPROVED' AND P.PAYMENT_DATE BETWEEN T.EFFECTIVE_DATE AND COALESCE(T.EXPIRY_DATE,'9999-12-31') WHERE NOT EXISTS(SELECT 1 FROM G2_4_FAILURES F WHERE F.SOURCE_ENTITY='PAYMENT_EXCEPTION' AND F._SOURCE_FILE_CONTENT_KEY=E._SOURCE_FILE_CONTENT_KEY AND F._SOURCE_FILE_ROW_NUMBER=E._SOURCE_FILE_ROW_NUMBER);
INSERT OVERWRITE INTO SILVER.SLA_EVENT SELECT TRIM(S.SLA_EVENT_ID),TRIM(S.EXCEPTION_ID),UPPER(TRIM(S.SLA_TYPE)),TRY_TO_TIMESTAMP_NTZ(S.SLA_START_TIMESTAMP),TRY_TO_TIMESTAMP_NTZ(S.SLA_DUE_TIMESTAMP),COALESCE(TRY_TO_BOOLEAN(S.SLA_BREACHED_FLAG),TRY_TO_NUMBER(S.BREACH_MINUTES)>0),GREATEST(0,COALESCE(TRY_TO_NUMBER(S.BREACH_MINUTES),0)),COALESCE(TRY_TO_BOOLEAN(S.ESCALATION_REQUIRED),TRY_TO_NUMBER(S.BREACH_MINUTES)>0),IFF(COALESCE(TRY_TO_BOOLEAN(S.SLA_BREACHED_FLAG),FALSE),'BREACHED',UPPER(TRIM(S.SLA_STATUS))),S._SOURCE_ID,CONCAT('SLA_EVENT|',S._SOURCE_FILE_CONTENT_KEY,'|',S._SOURCE_FILE_ROW_NUMBER),S._SOURCE_FILE_NAME,S._SOURCE_FILE_ROW_NUMBER,S._INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),S._SYNTHETIC_FLAG,'PASS' FROM BRONZE.SLA_EVENT_RAW S JOIN SILVER.PAYMENT_EXCEPTION E ON S.EXCEPTION_ID=E.EXCEPTION_ID WHERE NOT EXISTS(SELECT 1 FROM G2_4_FAILURES F WHERE F.SOURCE_ENTITY='SLA_EVENT' AND F._SOURCE_FILE_CONTENT_KEY=S._SOURCE_FILE_CONTENT_KEY AND F._SOURCE_FILE_ROW_NUMBER=S._SOURCE_FILE_ROW_NUMBER);
INSERT OVERWRITE INTO SILVER.OPERATIONS_USER SELECT TRIM(OPERATIONS_USER_ID),TRIM(TEAM_ID),TRIM(DISPLAY_NAME),TRIM(BUSINESS_PERSONA),UPPER(TRIM(REGION)),UPPER(TRIM(EMPLOYMENT_STATUS)),_SOURCE_ID,CONCAT('OPERATIONS_USER|',_SOURCE_FILE_CONTENT_KEY,'|',_SOURCE_FILE_ROW_NUMBER),_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),_SYNTHETIC_FLAG,'PASS' FROM BRONZE.OPERATIONS_USER_RAW WHERE OPERATIONS_USER_ID IS NOT NULL;
INSERT OVERWRITE INTO SILVER.OPERATIONS_TEAM SELECT TRIM(T.TEAM_ID),TRIM(T.TEAM_NAME),UPPER(TRIM(T.REGION)),TRIM(T.MANAGER_ID),UPPER(TRIM(T.TEAM_STATUS)),T._SOURCE_ID,CONCAT('OPERATIONS_TEAM|',T._SOURCE_FILE_CONTENT_KEY,'|',T._SOURCE_FILE_ROW_NUMBER),T._SOURCE_FILE_NAME,T._SOURCE_FILE_ROW_NUMBER,T._INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),T._SYNTHETIC_FLAG,'PASS' FROM BRONZE.OPERATIONS_TEAM_RAW T JOIN SILVER.OPERATIONS_USER U ON T.MANAGER_ID=U.OPERATIONS_USER_ID AND U.BUSINESS_PERSONA='Banking Operations Manager' AND U.EMPLOYMENT_STATUS='ACTIVE';
INSERT OVERWRITE INTO SILVER.GOVERNANCE_REFERENCE SELECT TRIM(GOVERNANCE_REFERENCE_ID),UPPER(TRIM(ASSET_TYPE)),TRIM(ASSET_IDENTIFIER),UPPER(TRIM(CLASSIFICATION)),UPPER(TRIM(SENSITIVITY_LEVEL)),TRIM(PERMITTED_PURPOSE),TRIM(OWNER),TRY_TO_DATE(EFFECTIVE_DATE),TRY_TO_DATE(EXPIRY_DATE),UPPER(TRIM(GOVERNANCE_STATUS)),_SOURCE_ID,CONCAT('GOVERNANCE_REFERENCE|',_SOURCE_FILE_CONTENT_KEY,'|',_SOURCE_FILE_ROW_NUMBER),_SOURCE_FILE_NAME,_SOURCE_FILE_ROW_NUMBER,_INGESTION_RUN_ID,$TRANSFORMATION_RUN_ID,$TRACE_ID,CURRENT_TIMESTAMP(),_SYNTHETIC_FLAG,'PASS' FROM BRONZE.GOVERNANCE_REFERENCE_RAW WHERE GOVERNANCE_REFERENCE_ID IS NOT NULL AND TRY_TO_DATE(EFFECTIVE_DATE) IS NOT NULL;

-- Per-entity reconciliation evidence is derived from immutable Bronze and current run state.
INSERT INTO AUDIT.TRANSFORMATION_ENTITY_EVIDENCE
WITH C AS (
 SELECT 'CUSTOMER' E,(SELECT COUNT(*) FROM BRONZE.CUSTOMER_RAW) B,(SELECT COUNT(*) FROM SILVER.CUSTOMER) S
 UNION ALL SELECT 'ACCOUNT',(SELECT COUNT(*) FROM BRONZE.ACCOUNT_RAW),(SELECT COUNT(*) FROM SILVER.ACCOUNT)
 UNION ALL SELECT 'PAYMENT',(SELECT COUNT(*) FROM BRONZE.PAYMENT_RAW),(SELECT COUNT(*) FROM SILVER.PAYMENT)
 UNION ALL SELECT 'PAYMENT_EXCEPTION',(SELECT COUNT(*) FROM BRONZE.PAYMENT_EXCEPTION_RAW),(SELECT COUNT(*) FROM SILVER.PAYMENT_EXCEPTION)
 UNION ALL SELECT 'SLA_EVENT',(SELECT COUNT(*) FROM BRONZE.SLA_EVENT_RAW),(SELECT COUNT(*) FROM SILVER.SLA_EVENT)
 UNION ALL SELECT 'OPERATIONS_TEAM',(SELECT COUNT(*) FROM BRONZE.OPERATIONS_TEAM_RAW),(SELECT COUNT(*) FROM SILVER.OPERATIONS_TEAM)
 UNION ALL SELECT 'OPERATIONS_USER',(SELECT COUNT(*) FROM BRONZE.OPERATIONS_USER_RAW),(SELECT COUNT(*) FROM SILVER.OPERATIONS_USER)
 UNION ALL SELECT 'REFERENCE_EXCEPTION_REASON',(SELECT COUNT(*) FROM BRONZE.REFERENCE_EXCEPTION_REASON_RAW),(SELECT COUNT(*) FROM SILVER.REFERENCE_EXCEPTION_REASON)
 UNION ALL SELECT 'REFERENCE_PAYMENT_THRESHOLD',(SELECT COUNT(*) FROM BRONZE.REFERENCE_PAYMENT_THRESHOLD_RAW),(SELECT COUNT(*) FROM SILVER.REFERENCE_PAYMENT_THRESHOLD)
 UNION ALL SELECT 'GOVERNANCE_REFERENCE',(SELECT COUNT(*) FROM BRONZE.GOVERNANCE_REFERENCE_RAW),(SELECT COUNT(*) FROM SILVER.GOVERNANCE_REFERENCE)
), Q AS (SELECT SOURCE_ENTITY E,COUNT(*) Q FROM G2_4_FAILURES GROUP BY SOURCE_ENTITY)
SELECT $TRANSFORMATION_RUN_ID,$TRACE_ID,C.E,(SELECT MAX(_INGESTION_RUN_ID) FROM BRONZE.PAYMENT_RAW),C.B,C.S,COALESCE(Q.Q,0),COALESCE(Q.Q,0),'COMPLETED',CURRENT_TIMESTAMP(),LAST_QUERY_ID() FROM C LEFT JOIN Q USING(E);
UPDATE AUDIT.TRANSFORMATION_RUN SET STATUS='COMPLETED',TRANSFORMATION_COMPLETED_AT=CURRENT_TIMESTAMP(),QUERY_ID=LAST_QUERY_ID() WHERE TRANSFORMATION_RUN_ID=$TRANSFORMATION_RUN_ID;
